(7528459, 1202973, 97225, '<td valign="top">Congratulations Robert. Lovely shot.</td>', 'Congratulations Robert. Lovely shot.', '2017-08-12 03:56:12.000000', NULL, 0),
(7528478, 1203513, 100831, '<td valign="top">Great shot and title to match! Glad to see this made tt.</td>', 'Great shot and title to match! Glad to see this made tt.', '2017-08-12 10:51:40.000000', NULL, 0),
(7528523, 1203049, 59029, '<td valign="top">Greetings from the Critique Club!  I can see what you want to do with this shot, show a wide array of all types of tools, probably near and dear to your heart.  Indeed, each tool on its own is well-lit and shows detail. But comp leaves much to be desired, though, it looks like the early stages of a catalogue shot for man-cave toys. This is a case of trying to jam too much into an image, and as a result every tool competes with all the others.  Esp as three of the four have red on them, a strong signifier colour.  Red needs to be used sparingly, as it immediately draws attention away from everything else.  It would have worked to just focus on one tool and put all your skills to work on it.<br/> <br/>Hope this helps, feel free to PM me<br/> <br/>Susan</td>', 'Greetings from the Critique Club!  I can see what you want to do with this shot, show a wide array of all types of tools, probably near and dear to your heart.  Indeed, each tool on its own is well-lit and shows detail. But comp leaves much to be desired, though, it looks like the early stages of a catalogue shot for man-cave toys. This is a case of trying to jam too much into an image, and as a result every tool competes with all the others.  Esp as three of the four have red on them, a strong signifier colour.  Red needs to be used sparingly, as it immediately draws attention away from everything else.  It would have worked to just focus on one tool and put all your skills to work on it. Hope this helps, feel free to PM me Susan', '2017-08-12 19:23:33.000000', NULL, 0),
(7528524, 1203299, 59029, '<td valign="top">Greetings from the Critique Club!  Never would have guessed this as one of yours, Marcel :-) Very intriguing image and clever with the knife between the tines of the fork completing the fork''s reflection.  Definitely tools, it might have helped to add a little more, possibly something to provide a hit of colour as there is so much grey in this image.  Maybe even just a carefully placed sprig of parsley? I see you shot quite fast for slowing down the speed a lot and using a tripod should have helped to bring in some light and perhaps add some contrast to the tools in question.  The basic idea is brilliant, it just needs a little more work.<br/> <br/>Keep up the great work and look forward to seeing more of it soon!<br/> <br/>Susan</td>', 'Greetings from the Critique Club!  Never would have guessed this as one of yours, Marcel :-) Very intriguing image and clever with the knife between the tines of the fork completing the fork''s reflection.  Definitely tools, it might have helped to add a little more, possibly something to provide a hit of colour as there is so much grey in this image.  Maybe even just a carefully placed sprig of parsley? I see you shot quite fast for slowing down the speed a lot and using a tripod should have helped to bring in some light and perhaps add some contrast to the tools in question.  The basic idea is brilliant, it just needs a little more work. Keep up the great work and look forward to seeing more of it soon! Susan', '2017-08-12 19:28:37.000000', NULL, 0),
(7531022, 1203496, 50641, '<td valign="top">Fantastic depth.</td>', 'Fantastic depth.', '2017-08-26 04:42:04.000000', NULL, 0);
